import json
p=json.load(open('/tmp/posts.json'))
print(type(p), len(p))
for x in p:
 if x.get('pinned') or 'round' in (x.get('title','')+x.get('body','')).lower() or 'contrad' in (x.get('title','')+x.get('body','')).lower(): print(x)
